-- Presentation projections only. m15_01_usage remains the source quota authority.
create table public.organization_usage_meters (
 organization_id uuid primary key references public.organizations(id),
 active_members bigint, reserved_invitations bigint, products bigint,
 storage_bytes bigint, storage_reserved_bytes bigint, protected_storage_bytes bigint,
 seats_ready boolean not null default false, products_ready boolean not null default false,
 storage_ready boolean not null default false, protected_storage_ready boolean not null default false,
 seats_reasons text[] not null default array['meter_missing'], products_reasons text[] not null default array['meter_missing'],
 storage_reasons text[] not null default array['meter_missing'], protected_storage_reasons text[] not null default array['meter_missing'],
 meter_version bigint not null default 1 check(meter_version between 1 and 9007199254740991),
 source_version bigint not null default 1 check(source_version between 1 and 9007199254740991),
 next_invitation_expiry timestamptz, reconciled_at timestamptz, updated_at timestamptz not null default clock_timestamp(),
 check(active_members between 0 and 9007199254740991), check(reserved_invitations between 0 and 9007199254740991),
 check(products between 0 and 9007199254740991), check(storage_bytes between 0 and 9007199254740991),
 check(storage_reserved_bytes between 0 and 9007199254740991), check(protected_storage_bytes between 0 and 9007199254740991)
);
alter table public.organization_usage_meters enable row level security;
revoke all on public.organization_usage_meters from public,anon,authenticated,service_role;
grant select on public.organization_usage_meters to service_role;
create index m15_02_invitation_expiry on public.invitations(organization_id,expires_at) where status='pending';
create index m15_02_invitation_email on public.invitations(organization_id,lower(email),expires_at) where status='pending';

-- Generated bytes require an actual source owner, never just a tenant-looking path.
create function public.m15_02_generated_objects(p_organization_id uuid,p_bucket text default null,p_object_path text default null)
returns table(bucket text,object_path text) language sql stable security definer set search_path=pg_catalog,public as $$
 select owned.bucket,owned.object_path from (
 select 'audit-exports'::text as bucket,artifact->>'objectPath' as object_path from public.audit_export_jobs where organization_id=p_organization_id and artifact->>'objectPath' is not null
 union all select 'filtered-exports',part->>'objectPath' from public.export_jobs j cross join lateral jsonb_array_elements(j.parts) part where j.organization_id=p_organization_id
 union all select 'technical-file-snapshot-exports',v.path from public.technical_file_snapshot_exports e cross join lateral (values(e.manifest_object_path),(e.archive_object_path),(e.pdf_object_path))v(path) where e.organization_id=p_organization_id and v.path is not null
 union all select 'technical-file-declarations',pdf_object_path from public.technical_file_declarations where organization_id=p_organization_id and pdf_object_path is not null
 union all select 'tenant-exports',artifact_object_path from public.organization_export_jobs where organization_id=p_organization_id and artifact_object_path is not null
 union all select 'tenant-exports',p.object_path from public.organization_export_parts p where organization_id=p_organization_id
 union all select 'tenant-exports',snapshot_object_path from public.organization_export_artifact_snapshots where organization_id=p_organization_id
 union all select 'evidence-watermark-exports',derivative_object_key from public.evidence_document_watermark_exports where organization_id=p_organization_id and derivative_object_key is not null
 union all select storage_bucket,storage_object_path from public.reporting_stage_packages where organization_id=p_organization_id
 union all select storage_bucket,storage_object_path from public.reporting_obligation_evidence_packs where organization_id=p_organization_id
 ) owned where (p_bucket is null or owned.bucket=p_bucket) and (p_object_path is null or owned.object_path=p_object_path)
$$;
create function public.m15_02_object_owners(p_bucket text,p_path text) returns table(organization_id uuid) language sql stable security definer set search_path=pg_catalog,public as $$
 select organization_id from public.evidence_document_versions where object_bucket=p_bucket and object_key=p_path
 union select organization_id from public.sbom_sources where p_bucket='sbom-originals' and staging_storage_key=p_path
 union select organization_id from public.sbom_raw_objects where storage_bucket=p_bucket and storage_key=p_path
 union select organization_id from public.organization_branding_assets where p_bucket='organization-branding' and object_path=p_path
 union select organization_id from public.product_import_jobs where p_bucket='product-imports' and source_object_path=p_path and source_deleted_at is null
 union select organization_id from public.product_security_update_artifacts where p_bucket='security-update-artifacts' and object_key=p_path
 union select organization_id from public.audit_export_jobs where p_bucket='audit-exports' and artifact->>'objectPath'=p_path
 union select organization_id from public.export_jobs where p_bucket='filtered-exports' and exists(select 1 from jsonb_array_elements(parts)x where x->>'objectPath'=p_path)
 union select organization_id from public.technical_file_snapshot_exports where p_bucket='technical-file-snapshot-exports' and p_path in (manifest_object_path,archive_object_path,pdf_object_path)
 union select organization_id from public.technical_file_declarations where p_bucket='technical-file-declarations' and pdf_object_path=p_path
 union select organization_id from public.organization_export_jobs where p_bucket='tenant-exports' and artifact_object_path=p_path
 union select organization_id from public.organization_export_parts where p_bucket='tenant-exports' and object_path=p_path
 union select organization_id from public.organization_export_artifact_snapshots where p_bucket='tenant-exports' and snapshot_object_path=p_path
 union select organization_id from public.evidence_document_watermark_exports where p_bucket='evidence-watermark-exports' and derivative_object_key=p_path
 union select organization_id from public.reporting_stage_packages where storage_bucket=p_bucket and storage_object_path=p_path
 union select organization_id from public.reporting_obligation_evidence_packs where storage_bucket=p_bucket and storage_object_path=p_path
$$;
create function public.m15_02_refresh_seats(p_organization_id uuid) returns void
language plpgsql security definer set search_path=pg_catalog,public as $$
declare a bigint; r bigint; expiry timestamptz;
begin
 if not exists(select 1 from public.organization_usage_meters where organization_id=p_organization_id) then perform public.m15_02_rebuild_meter(p_organization_id);return;end if;
 select count(*) into a from public.organization_members m join public.users u on u.id=m.user_id and u.is_active where m.organization_id=p_organization_id;
 select count(distinct lower(i.email)),min(i.expires_at) into r,expiry from public.invitations i where i.organization_id=p_organization_id and i.status='pending' and i.expires_at>clock_timestamp()
 and not exists(select 1 from public.organization_members m join public.users u on u.id=m.user_id and u.is_active where m.organization_id=i.organization_id and lower(u.email)=lower(i.email));
 update public.organization_usage_meters set active_members=a,reserved_invitations=r,seats_ready=true,seats_reasons='{}',next_invitation_expiry=expiry,
 meter_version=least(meter_version+1,9007199254740991),source_version=least(source_version+1,9007199254740991),updated_at=clock_timestamp() where organization_id=p_organization_id;
end $$;
create function public.m15_02_rebuild_meter(p_organization_id uuid,p_reconciled boolean default false) returns void
language plpgsql security definer set search_path=pg_catalog,public as $$
declare b numeric; r numeric; p numeric; bad boolean; customer_bad boolean; ready boolean;
begin
 perform public.m15_01_lock(p_organization_id);
 insert into public.organization_usage_meters(organization_id) values(p_organization_id) on conflict do nothing;
 perform public.m15_02_refresh_seats(p_organization_id);
 select coalesce(sum(observed_bytes) filter(where state='completed' and not protected_input),0),
 coalesce(sum(reserved_bytes) filter(where state in ('reserved','uploading','uncertain') and not protected_input),0),
 coalesce(sum(case when state='completed' then observed_bytes else reserved_bytes end) filter(where protected_input and state in ('reserved','uploading','uncertain','completed')),0),
 coalesce(bool_or(state='completed' and observed_bytes is null and protected_input),false),coalesce(bool_or(state='completed' and observed_bytes is null and not protected_input),false) into b,r,p,bad,customer_bad
 from public.organization_storage_admissions where organization_id=p_organization_id;
 select p+coalesce(sum(case when so.metadata->>'size' ~ '^[0-9]{1,16}$' and (so.metadata->>'size')::numeric<=9007199254740991 then (so.metadata->>'size')::numeric else 0 end),0),
 bad or coalesce(bool_or(so.metadata->>'size' is null or so.metadata->>'size' !~ '^[0-9]{1,16}$' or case when so.metadata->>'size' ~ '^[0-9]{1,16}$' then (so.metadata->>'size')::numeric>9007199254740991 else false end),false)
 into p,bad from storage.objects so join (select distinct bucket,object_path from public.m15_02_generated_objects(p_organization_id)) g on g.bucket=so.bucket_id and g.object_path=so.name
 where not exists(select 1 from public.organization_storage_admissions a where a.organization_id=p_organization_id and a.bucket=so.bucket_id and a.object_path=so.name);
 ready:=public.m15_01_storage_accounting_ready(p_organization_id) and not customer_bad and b+r<=9007199254740991
 and not exists(select 1 from public.m15_01_customer_objects()c where c.organization_id=p_organization_id and (select count(distinct other.organization_id) from public.m15_01_customer_objects()other where other.bucket=c.bucket and other.object_path=c.object_path)>1);
 update public.organization_usage_meters set products=(select count(*) from public.products where organization_id=p_organization_id and archived_at is null),products_ready=true,products_reasons='{}',
 storage_bytes=case when b<=9007199254740991 then b::bigint end,storage_reserved_bytes=case when r<=9007199254740991 then r::bigint end,storage_ready=ready,
 storage_reasons=case when ready then '{}'::text[] else array['storage_accounting_unavailable'] end,
 protected_storage_bytes=case when p<=9007199254740991 then p::bigint end,protected_storage_ready=not bad and p<=9007199254740991,
 protected_storage_reasons=case when not bad and p<=9007199254740991 then '{}'::text[] else array['protected_storage_size_unknown'] end,
 reconciled_at=case when p_reconciled then clock_timestamp() else reconciled_at end,updated_at=clock_timestamp() where organization_id=p_organization_id;
end $$;

-- Lock all affected tenants in sorted order before source and meter rows.
create function public.m15_02_source_lock() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare o uuid; ids uuid[];
begin
 if tg_table_schema='storage' then
  select array_agg(distinct id order by id) into ids from public.organizations where id::text in (split_part(coalesce(new.name,''),'/',1),split_part(coalesce(old.name,''),'/',1),split_part(coalesce(new.name,''),'/',2),split_part(coalesce(old.name,''),'/',2)) or id in (select organization_id from public.m15_02_object_owners(new.bucket_id,new.name) union select organization_id from public.m15_02_object_owners(old.bucket_id,old.name));
 elsif tg_table_name='users' then
  select array_agg(organization_id order by organization_id) into ids from public.organization_members where user_id=coalesce(new.id,old.id);
 else ids:=array[(to_jsonb(new)->>'organization_id')::uuid,(to_jsonb(old)->>'organization_id')::uuid]; end if;
 for o in select distinct unnest(ids) as id order by id loop if o is not null then perform public.m15_01_lock(o);end if;end loop;
 return coalesce(new,old);
end $$;
create function public.m15_02_source_refs(p_table text,p_row jsonb) returns table(bucket text,object_path text) language plpgsql immutable set search_path=pg_catalog,public as $$
begin
 if p_row is null then return;end if;
 case p_table
 when 'evidence_document_versions' then return query select p_row->>'object_bucket',p_row->>'object_key';
 when 'sbom_sources' then return query select 'sbom-originals'::text,p_row->>'staging_storage_key';
 when 'sbom_raw_objects' then return query select p_row->>'storage_bucket',p_row->>'storage_key';
 when 'organization_branding_assets' then return query select 'organization-branding'::text,p_row->>'object_path';
 when 'product_import_jobs' then if p_row->>'source_deleted_at' is null then return query select 'product-imports'::text,p_row->>'source_object_path';end if;
 when 'product_security_update_artifacts' then return query select 'security-update-artifacts'::text,p_row->>'object_key';
 when 'audit_export_jobs' then return query select 'audit-exports'::text,p_row->'artifact'->>'objectPath';
 when 'export_jobs' then return query select 'filtered-exports'::text,x->>'objectPath' from jsonb_array_elements(p_row->'parts')x;
 when 'technical_file_snapshot_exports' then return query select 'technical-file-snapshot-exports'::text,x from unnest(array[p_row->>'manifest_object_path',p_row->>'archive_object_path',p_row->>'pdf_object_path'])x;
 when 'technical_file_declarations' then return query select 'technical-file-declarations'::text,p_row->>'pdf_object_path';
 when 'organization_export_jobs' then return query select 'tenant-exports'::text,p_row->>'artifact_object_path';
 when 'organization_export_parts' then return query select 'tenant-exports'::text,p_row->>'object_path';
 when 'organization_export_artifact_snapshots' then return query select 'tenant-exports'::text,p_row->>'snapshot_object_path';
 when 'evidence_document_watermark_exports' then return query select 'evidence-watermark-exports'::text,p_row->>'derivative_object_key';
 when 'reporting_stage_packages','reporting_obligation_evidence_packs' then return query select p_row->>'storage_bucket',p_row->>'storage_object_path';
 else return;
 end case;
end $$;
create function public.m15_02_object_bytes(p_metadata jsonb) returns bigint language sql immutable set search_path=pg_catalog,public as $$
 select case when p_metadata->>'size' ~ '^[0-9]{1,16}$' then case when (p_metadata->>'size')::numeric<=9007199254740991 then (p_metadata->>'size')::bigint end end
$$;
create function public.m15_02_apply_delta(p_organization_id uuid,p_column text,p_delta numeric,p_group text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$
declare current_value numeric;next_value numeric;ready_column text;reasons_column text;
begin
 if p_column not in ('products','storage_bytes','storage_reserved_bytes','protected_storage_bytes') or p_group not in ('products','storage','protected_storage') then raise exception 'invalid_meter_delta';end if;
 if not exists(select 1 from public.organization_usage_meters where organization_id=p_organization_id) then perform public.m15_02_rebuild_meter(p_organization_id);return;end if;
 ready_column:=p_group||'_ready';reasons_column:=p_group||'_reasons';
 execute format('select %I from public.organization_usage_meters where organization_id=$1',p_column) into current_value using p_organization_id;
 next_value:=current_value+p_delta;
 if next_value is null or next_value not between 0 and 9007199254740991 then
  execute format('update public.organization_usage_meters set %I=false,%I=array[''meter_inconsistent''],meter_version=least(meter_version+1,9007199254740991),source_version=least(source_version+1,9007199254740991),updated_at=clock_timestamp() where organization_id=$1',ready_column,reasons_column) using p_organization_id;
 else
  execute format('update public.organization_usage_meters set %I=$2,meter_version=least(meter_version+1,9007199254740991),source_version=least(source_version+1,9007199254740991),updated_at=clock_timestamp() where organization_id=$1',p_column) using p_organization_id,next_value::bigint;
 end if;
 if p_group='storage' then
  update public.organization_usage_meters set storage_ready=false,storage_reasons=array['meter_inconsistent'] where organization_id=p_organization_id and storage_bytes::numeric+storage_reserved_bytes::numeric>9007199254740991;
 end if;
end $$;
create function public.m15_02_source_changed() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $$
declare o uuid;ids uuid[];old_row jsonb:=to_jsonb(old);new_row jsonb:=to_jsonb(new);before_value numeric;after_value numeric;ref record;size bigint;old_size bigint;col text;grp text;old_refs jsonb;new_refs jsonb;
begin
 if tg_table_name='users' then
  if old.is_active is not distinct from new.is_active and old.email is not distinct from new.email then return new;end if;
  for o in select organization_id from public.organization_members where user_id=new.id order by organization_id loop perform public.m15_02_refresh_seats(o);end loop;return new;
 end if;
 if tg_table_schema='storage' then
  if tg_op='UPDATE' and (old.bucket_id,old.name,old.metadata->>'size') is not distinct from (new.bucket_id,new.name,new.metadata->>'size') then return new;end if;
  select array_agg(distinct id order by id) into ids from public.organizations where id::text in (split_part(coalesce(new.name,''),'/',1),split_part(coalesce(old.name,''),'/',1),split_part(coalesce(new.name,''),'/',2),split_part(coalesce(old.name,''),'/',2)) or id in (select organization_id from public.m15_02_object_owners(new.bucket_id,new.name) union select organization_id from public.m15_02_object_owners(old.bucket_id,old.name));
  for o in select unnest(ids) loop
   before_value:=0;after_value:=0;
   if tg_op<>'INSERT' and exists(select 1 from public.m15_02_generated_objects(o,old.bucket_id,old.name) g) and not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=old.bucket_id and a.object_path=old.name) then before_value:=public.m15_02_object_bytes(old.metadata);end if;
   if tg_op<>'DELETE' and exists(select 1 from public.m15_02_generated_objects(o,new.bucket_id,new.name) g) and not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=new.bucket_id and a.object_path=new.name) then after_value:=public.m15_02_object_bytes(new.metadata);end if;
   if before_value is distinct from after_value then perform public.m15_02_apply_delta(o,'protected_storage_bytes',after_value-before_value,'protected_storage');end if;
   if tg_op<>'DELETE' and exists(select 1 from public.m15_01_customer_objects() c where c.organization_id=o and c.bucket=new.bucket_id and c.object_path=new.name) and (public.m15_02_object_bytes(new.metadata) is null or not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=new.bucket_id and a.object_path=new.name)) then update public.organization_usage_meters set storage_ready=false,storage_reasons=array['storage_accounting_unavailable'],meter_version=least(meter_version+1,9007199254740991),source_version=least(source_version+1,9007199254740991) where organization_id=o;end if;
  end loop;
  return coalesce(new,old);
 end if;
 if tg_table_name in ('organization_members','invitations') then
  if tg_op='UPDATE' and ((tg_table_name='organization_members' and old_row-array['role','updated_at'] is not distinct from new_row-array['role','updated_at']) or (tg_table_name='invitations' and old_row->'organization_id'=new_row->'organization_id' and old_row->'email'=new_row->'email' and old_row->'status'=new_row->'status' and old_row->'expires_at'=new_row->'expires_at')) then return new;end if;
  for o in select distinct x from unnest(array[(old_row->>'organization_id')::uuid,(new_row->>'organization_id')::uuid])x where x is not null order by x loop perform public.m15_02_refresh_seats(o);end loop;
 elsif tg_table_name='products' then
  if tg_op='UPDATE' and (old.organization_id,old.archived_at) is not distinct from (new.organization_id,new.archived_at) then return new;end if;
  for o in select distinct x from unnest(array[(old_row->>'organization_id')::uuid,(new_row->>'organization_id')::uuid])x where x is not null order by x loop
   before_value:=case when old_row->>'organization_id'=o::text and old_row->>'archived_at' is null then 1 else 0 end;
   after_value:=case when new_row->>'organization_id'=o::text and new_row->>'archived_at' is null then 1 else 0 end;
   if before_value<>after_value then perform public.m15_02_apply_delta(o,'products',after_value-before_value,'products');end if;
  end loop;
 elsif tg_table_name='organization_storage_admissions' then
  if tg_op='UPDATE' and old_row-array['updated_at','content_sha256','token_digest','expires_at','content_type','source_context','actor_user_id','capability'] is not distinct from new_row-array['updated_at','content_sha256','token_digest','expires_at','content_type','source_context','actor_user_id','capability'] then return new;end if;
  for o in select distinct x from unnest(array[(old_row->>'organization_id')::uuid,(new_row->>'organization_id')::uuid])x where x is not null order by x loop
   if (old_row->>'bucket',old_row->>'object_path',old_row->>'organization_id') is distinct from (new_row->>'bucket',new_row->>'object_path',new_row->>'organization_id') then
    if old_row->>'organization_id'=o::text and exists(select 1 from public.m15_02_generated_objects(o,old_row->>'bucket',old_row->>'object_path')) then
     select public.m15_02_object_bytes(metadata) into size from storage.objects where bucket_id=old_row->>'bucket' and name=old_row->>'object_path';
     if found then perform public.m15_02_apply_delta(o,'protected_storage_bytes',size,'protected_storage');end if;
    end if;
    if new_row->>'organization_id'=o::text and exists(select 1 from public.m15_02_generated_objects(o,new_row->>'bucket',new_row->>'object_path')) then
     select public.m15_02_object_bytes(metadata) into size from storage.objects where bucket_id=new_row->>'bucket' and name=new_row->>'object_path';
     if found then perform public.m15_02_apply_delta(o,'protected_storage_bytes',-size,'protected_storage');end if;
    end if;
   end if;
   foreach col in array array['storage_bytes','storage_reserved_bytes','protected_storage_bytes'] loop
    grp:=case when col='protected_storage_bytes' then 'protected_storage' else 'storage' end;
    before_value:=0;after_value:=0;
    if old_row->>'organization_id'=o::text then
     before_value:=case when col='storage_bytes' and old_row->>'state'='completed' and old_row->'protected_input'='false' then (old_row->>'observed_bytes')::numeric when col='storage_reserved_bytes' and old_row->>'state' in ('reserved','uploading','uncertain') and old_row->'protected_input'='false' then (old_row->>'reserved_bytes')::numeric when col='protected_storage_bytes' and old_row->'protected_input'='true' and old_row->>'state' in ('reserved','uploading','uncertain','completed') then case when old_row->>'state'='completed' then (old_row->>'observed_bytes')::numeric else (old_row->>'reserved_bytes')::numeric end else 0 end;
    end if;
    if new_row->>'organization_id'=o::text then
     after_value:=case when col='storage_bytes' and new_row->>'state'='completed' and new_row->'protected_input'='false' then (new_row->>'observed_bytes')::numeric when col='storage_reserved_bytes' and new_row->>'state' in ('reserved','uploading','uncertain') and new_row->'protected_input'='false' then (new_row->>'reserved_bytes')::numeric when col='protected_storage_bytes' and new_row->'protected_input'='true' and new_row->>'state' in ('reserved','uploading','uncertain','completed') then case when new_row->>'state'='completed' then (new_row->>'observed_bytes')::numeric else (new_row->>'reserved_bytes')::numeric end else 0 end;
    end if;
    if before_value is distinct from after_value then perform public.m15_02_apply_delta(o,col,after_value-before_value,grp);end if;
   end loop;
  end loop;
 else
  if tg_table_name in ('evidence_document_versions','sbom_sources','sbom_raw_objects','organization_branding_assets','product_import_jobs','product_security_update_artifacts') then
   select coalesce(jsonb_agg(jsonb_build_array(bucket,object_path) order by bucket,object_path),'[]') into old_refs from public.m15_02_source_refs(tg_table_name,old_row) where object_path is not null;
   select coalesce(jsonb_agg(jsonb_build_array(bucket,object_path) order by bucket,object_path),'[]') into new_refs from public.m15_02_source_refs(tg_table_name,new_row) where object_path is not null;
   if old_refs is not distinct from new_refs and old_row->'organization_id' is not distinct from new_row->'organization_id' then return coalesce(new,old);end if;
   o:=(new_row->>'organization_id')::uuid;
   for ref in select * from public.m15_02_source_refs(tg_table_name,new_row) where object_path is not null loop
    if exists(select 1 from storage.objects so where so.bucket_id=ref.bucket and so.name=ref.object_path and (public.m15_02_object_bytes(so.metadata) is null or not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=ref.bucket and a.object_path=ref.object_path))) then
     update public.organization_usage_meters set storage_ready=false,storage_reasons=array['storage_accounting_unavailable'],meter_version=least(meter_version+1,9007199254740991),source_version=least(source_version+1,9007199254740991) where organization_id=o;
    end if;
   end loop;
   return coalesce(new,old);
  end if;
  select coalesce(jsonb_agg(jsonb_build_array(bucket,object_path) order by bucket,object_path),'[]') into old_refs from public.m15_02_source_refs(tg_table_name,old_row) where object_path is not null;
  select coalesce(jsonb_agg(jsonb_build_array(bucket,object_path) order by bucket,object_path),'[]') into new_refs from public.m15_02_source_refs(tg_table_name,new_row) where object_path is not null;
  if old_refs is not distinct from new_refs and old_row->'organization_id' is not distinct from new_row->'organization_id' then return coalesce(new,old);end if;
  for o in select distinct x from unnest(array[(old_row->>'organization_id')::uuid,(new_row->>'organization_id')::uuid])x where x is not null order by x loop
   for ref in select distinct r.bucket,r.object_path from public.m15_02_source_refs(tg_table_name,old_row)r where old_row->>'organization_id'=o::text and r.object_path is not null and not exists(select 1 from public.m15_02_source_refs(tg_table_name,new_row)n where n.bucket=r.bucket and n.object_path=r.object_path and new_row->>'organization_id'=o::text) loop
    if not exists(select 1 from public.m15_02_generated_objects(o,ref.bucket,ref.object_path)g) and not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=ref.bucket and a.object_path=ref.object_path) then
     select public.m15_02_object_bytes(metadata) into size from storage.objects where bucket_id=ref.bucket and name=ref.object_path;
     if found then perform public.m15_02_apply_delta(o,'protected_storage_bytes',-size,'protected_storage');end if;
    end if;
   end loop;
   for ref in select distinct r.bucket,r.object_path from public.m15_02_source_refs(tg_table_name,new_row)r where new_row->>'organization_id'=o::text and r.object_path is not null and not exists(select 1 from public.m15_02_source_refs(tg_table_name,old_row)n where n.bucket=r.bucket and n.object_path=r.object_path and old_row->>'organization_id'=o::text) loop
    if (select count(*) from public.m15_02_generated_objects(o,ref.bucket,ref.object_path)g)=(select count(*) from public.m15_02_source_refs(tg_table_name,new_row)n where n.bucket=ref.bucket and n.object_path=ref.object_path) and not exists(select 1 from public.organization_storage_admissions a where a.organization_id=o and a.bucket=ref.bucket and a.object_path=ref.object_path) then
     select public.m15_02_object_bytes(metadata) into size from storage.objects where bucket_id=ref.bucket and name=ref.object_path;
     if found then perform public.m15_02_apply_delta(o,'protected_storage_bytes',size,'protected_storage');end if;
    end if;
   end loop;
  end loop;
 end if;
 return coalesce(new,old);
end $$;
do $$ declare t text;begin
 foreach t in array array['organization_members','invitations','products','organization_storage_admissions','audit_export_jobs','export_jobs','technical_file_snapshot_exports','technical_file_declarations','organization_export_jobs','organization_export_parts','organization_export_artifact_snapshots','evidence_document_watermark_exports','reporting_stage_packages','reporting_obligation_evidence_packs','evidence_document_versions','sbom_sources','sbom_raw_objects','organization_branding_assets','product_import_jobs','product_security_update_artifacts'] loop
  execute format('create trigger aaa_m15_02_lock before insert or update or delete on public.%I for each row execute function public.m15_02_source_lock()',t);
  execute format('create trigger m15_02_meter after insert or update or delete on public.%I for each row execute function public.m15_02_source_changed()',t);
 end loop;
end $$;
create trigger aaa_m15_02_lock before update of is_active,email on public.users for each row execute function public.m15_02_source_lock();
create trigger m15_02_meter after update of is_active,email on public.users for each row execute function public.m15_02_source_changed();
create trigger aaa_m15_02_lock before insert or update or delete on storage.objects for each row execute function public.m15_02_source_lock();
create trigger m15_02_meter after insert or update or delete on storage.objects for each row execute function public.m15_02_source_changed();
-- Existing upload reconciliation acquired an admission row first. Hoist tenant
-- locking before that row so its meter hook cannot reverse reconcile's order.
do $$ declare sig regprocedure; d text;begin
 foreach sig in array array['public.m15_01_reconcile_storage_upload(uuid,text)'::regprocedure,'public.m15_01_claim_storage_upload(uuid,text)'::regprocedure,'public.m15_01_prepare_storage_publication(uuid,text,text)'::regprocedure,'public.m15_01_reset_storage_upload(uuid,text)'::regprocedure] loop
  d:=pg_get_functiondef(sig);
  d:=regexp_replace(d,'\mbegin\M',E'begin\n perform public.m15_01_lock(organization_id) from public.organization_storage_admissions where operation_id=p_operation_id;','i');execute d;
 end loop;
end $$;
select public.m15_02_rebuild_meter(id,true) from public.organizations order by id;

create function public.m15_02_projection(p_organization_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare m public.organization_usage_meters%rowtype;
begin
 select * into m from public.organization_usage_meters where organization_id=p_organization_id;
 if m.next_invitation_expiry<=clock_timestamp() then
  perform public.m15_01_lock(p_organization_id);perform public.m15_02_refresh_seats(p_organization_id);
  select * into m from public.organization_usage_meters where organization_id=p_organization_id;
 end if;
 return jsonb_build_object('components',jsonb_build_object('activeMembers',case when m.seats_ready then m.active_members end,'reservedInvitations',case when m.seats_ready then m.reserved_invitations end,'products',case when m.products_ready then m.products end,'storageBytes',case when m.storage_ready then m.storage_bytes end,'storageReservedBytes',case when m.storage_ready then m.storage_reserved_bytes end,'protectedStorageBytes',case when m.protected_storage_ready then m.protected_storage_bytes end),
 'availability',jsonb_build_object('seats',case when m.seats_ready then 'ready' else 'unavailable' end,'products',case when m.products_ready then 'ready' else 'unavailable' end,'storage',case when m.storage_ready then 'ready' else 'unavailable' end,'protected_storage',case when m.protected_storage_ready then 'ready' else 'unavailable' end),
 'reasons',jsonb_build_object('seats',coalesce(m.seats_reasons,array['meter_missing']),'products',coalesce(m.products_reasons,array['meter_missing']),'storage',coalesce(m.storage_reasons,array['meter_missing']),'protected_storage',coalesce(m.protected_storage_reasons,array['meter_missing'])),
 'meterVersion',coalesce(m.meter_version,0),'reconciledAt',public.m7_snapshot_timestamp_utc(m.reconciled_at));
end $$;
create function public.m15_02_read_usage(p_organization_id uuid,p_actor_user_id uuid,p_expected_license_version integer default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare result jsonb; v integer; seq bigint; revision integer;
begin
 if not public.m15_01_actor_can(p_organization_id,p_actor_user_id,'can_view_licensing') then return jsonb_build_object('outcome','forbidden');end if;
 select version,issuance_sequence,policy_revision into v,seq,revision from public.organization_license_states where organization_id=p_organization_id;v:=coalesce(v,0);
 if p_expected_license_version is not null and p_expected_license_version<>v then return jsonb_build_object('outcome','conflict');end if;
 result:=public.m15_02_projection(p_organization_id);
 return result||jsonb_build_object('outcome',case when result->'availability' @> '{"seats":"ready","products":"ready","storage":"ready","protected_storage":"ready"}' then 'ready' else 'unavailable' end,'organizationId',p_organization_id,'observedAt',public.m7_snapshot_timestamp_utc(clock_timestamp()),'licenseVersion',v,'issuanceSequence',seq,'policyRevision',revision);
end $$;
create function public.m15_02_legacy_usage(p_organization_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare p jsonb;begin
 perform public.m15_02_projection(p_organization_id);
 select jsonb_build_object('activeMembers',active_members,'reservedInvitations',reserved_invitations,'products',products,'storageBytes',storage_bytes,'storageReservedBytes',storage_reserved_bytes,'protectedStorageBytes',protected_storage_bytes) into p from public.organization_usage_meters where organization_id=p_organization_id;
 if p is null or exists(select 1 from jsonb_each(p) x where x.value='null'::jsonb) then return public.m15_01_usage(p_organization_id);end if;
 return p;
end $$;
create function public.m15_02_legacy_accounting_ready(p_organization_id uuid) returns boolean language plpgsql security definer set search_path=pg_catalog,public as $$
declare ready boolean;begin
 select seats_ready and products_ready and storage_ready and protected_storage_ready into ready from public.organization_usage_meters where organization_id=p_organization_id;
 if not found then return public.m15_01_storage_accounting_ready(p_organization_id);end if;
 return ready;
end $$;
-- Frozen M15-01 presentation envelopes now read the private primary-key cache.
-- The authoritative m15_01_usage definition is deliberately left untouched.
do $$ declare sig regprocedure;d text;begin
 foreach sig in array array['public.m15_01_get_state(uuid,uuid)'::regprocedure,'public.m15_01_get_worker_state(uuid)'::regprocedure] loop
  d:=pg_get_functiondef(sig);d:=replace(d,'public.m15_01_usage(p_organization_id)','public.m15_02_legacy_usage(p_organization_id)');d:=replace(d,'public.m15_01_storage_accounting_ready(p_organization_id)','public.m15_02_legacy_accounting_ready(p_organization_id)');d:=replace(d,'coalesce((select storage_accounting_ready from public.organization_license_states where organization_id=p_organization_id),false)','public.m15_02_legacy_accounting_ready(p_organization_id)');execute d;
 end loop;
end $$;
alter function public.m15_01_get_state(uuid,uuid) volatile;
alter function public.m15_01_get_worker_state(uuid) volatile;
revoke all on function public.m15_02_generated_objects(uuid,text,text),public.m15_02_object_owners(text,text),public.m15_02_refresh_seats(uuid),public.m15_02_rebuild_meter(uuid,boolean),public.m15_02_source_lock(),public.m15_02_source_changed(),public.m15_02_source_refs(text,jsonb),public.m15_02_object_bytes(jsonb),public.m15_02_apply_delta(uuid,text,numeric,text),public.m15_02_projection(uuid),public.m15_02_legacy_usage(uuid),public.m15_02_legacy_accounting_ready(uuid),public.m15_02_read_usage(uuid,uuid,integer) from public,anon,authenticated,service_role;
grant execute on function public.m15_02_read_usage(uuid,uuid,integer) to service_role;
notify pgrst,'reload schema';
